import type { AppLocale } from "@/i18n/routing";

/**
 * Optional AI fallback for off-topic chats.
 *
 * The widget answers on-topic questions deterministically from the FAQ bundle
 * (`answerFromKnowledge`). A question the knowledge base cannot place is handed
 * here; the reply is generated by a free / generously-limited OpenAI-compatible
 * endpoint so the fallback carries no fixed cost.
 *
 * The layer is wired but **unconfigured by default**: with no `SUPPORT_AI_API_KEY`
 * in the environment `requestAiReply` returns `null` immediately, and the caller
 * drops to `fallbackReply`. Adding a key later is a pure environment change —
 * no code edit — because the base URL and model are read from the environment
 * too, so the same code targets any OpenAI-compatible provider.
 *
 * The prompt is deliberately narrow: the model is told to answer **only** from
 * the supplied platform facts and to defer to the human channels otherwise, so a
 * generous model cannot drift into inventing product features.
 */

const DEFAULT_MODEL = "meta-llama/llama-3.3-70b-instruct:free";
const DEFAULT_BASE_URL = "https://openrouter.ai/api/v1";
const REQUEST_TIMEOUT_MS = 12_000;
const MAX_REPLY_LENGTH = 1200;

export type AiReply = { text: string } | null;

type ChatCompletionResponse = {
  choices?: Array<{ message?: { content?: string } }>;
};

/** True when an API key is present, i.e. the fallback can actually run. */
export function isAiConfigured(): boolean {
  return Boolean(process.env.SUPPORT_AI_API_KEY);
}

/**
 * Ask the configured model for a reply, or resolve to `null`.
 *
 * `null` is returned for every failure — no key, a non-2xx response, a timeout,
 * or an empty completion — so the caller always has a safe, grounded path and a
 * provider outage never surfaces as an error to the visitor.
 */
export async function requestAiReply(
  message: string,
  locale: AppLocale,
  facts: string,
  signal?: AbortSignal,
): Promise<AiReply> {
  const apiKey = process.env.SUPPORT_AI_API_KEY;
  if (!apiKey) return null;

  const baseUrl = process.env.SUPPORT_AI_BASE_URL || DEFAULT_BASE_URL;
  const model = process.env.SUPPORT_AI_MODEL || DEFAULT_MODEL;

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  const onAbort = () => controller.abort();
  signal?.addEventListener("abort", onAbort, { once: true });

  try {
    const response = await fetch(`${baseUrl.replace(/\/$/, "")}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model,
        max_tokens: 400,
        temperature: 0.2,
        messages: [
          {
            role: "system",
            content: [
              "You are the İşBul KKTC support assistant.",
              `Reply in the visitor's language (locale: ${locale}).`,
              "Answer ONLY from the platform facts below; never invent features, prices or policies.",
              "If the facts do not cover the question, say so briefly and point the visitor to the human channels.",
              "Keep the reply under 120 words.",
              "",
              "Platform facts:",
              facts,
            ].join("\n"),
          },
          { role: "user", content: message },
        ],
      }),
      signal: controller.signal,
    });

    if (!response.ok) return null;

    const payload = (await response.json()) as ChatCompletionResponse;
    const text = payload.choices?.[0]?.message?.content?.trim();
    if (!text) return null;

    return { text: text.slice(0, MAX_REPLY_LENGTH) };
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
    signal?.removeEventListener("abort", onAbort);
  }
}
